def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    # Endgame improvements: always defect last round, retaliate immediately in final rounds.
    if n == 99:
        return 'D'
    if n == 98:
        if opp[-1] == 'D':
            return 'D'
        return 'C'
    if n >= 95 and opp[-1] == 'D':
        return 'D'

    recent_len = min(10, n)
    recent = opp[n-recent_len:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_ratio = recent_c / recent_len

    # Detect likely always-defect or always-cooperate patterns.
    if n >= 6:
        last6 = opp[-6:]
        if all(a == 'D' for a in last6):
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if all(a == 'C' for a in last6):
            return 'C'

    # Tit-for-tat with forgiveness and probing.
    if n >= 2:
        if opp[-1] == 'D' and me[-1] == 'C':
            if recent_ratio > 0.6:
                if rng.random() < 0.7:
                    return 'C'
                return 'D'
            else:
                if rng.random() < 0.15:
                    return 'C'
                return 'D'
        if opp[-1] == 'D' and me[-1] == 'D':
            if n % 7 == 0 or recent_ratio > 0.35:
                return 'C'
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if opp[-1] == 'C':
            if len(history) >= 3:
                last3 = opp[-3:]
                if last3 == ['C', 'C', 'D'] and me[-1] == 'C':
                    return 'D'
            return 'C'

    return 'C'
